var i=[{title:`Спершу перевірте, що це плато`,text:`Одне невдале заняття не є плато. Порівняйте кілька тижнів у подібних умовах: та сама вправа, навантаження, амплітуда та зусилля. Зміни обладнання, сну чи техніки можуть зробити ваші числа гіршими, навіть коли форма не падає. Записуйте достатньо деталей, щоб відрізнити справжню тенденцію від щоденних коливань.`},{title:`Перевірте основи`,text:`Чи ви завершували заняття? Чи опір лишався викликом, і чи ви відновлювалися між тренуваннями? Чи був обсяг правильним для вас? Іноді навантаження замале, а іноді воно вище, ніж потрібно. Підйом також може застоятися, бо ви не практикували цей рух регулярно, поки м’язи ще адаптуються.`},{title:`Зробіть одну корисну зміну`,text:`Якщо ви легко завершуєте повторення, додайте трохи навантаження або використайте подвійну прогресію. Якщо втома наростає, а результативність падає, на деякий час скоротіть складні підходи або переставте розклад. Якщо один рух перестав покращуватися, спробуйте змінити техніку чи близьку варіацію і залиште решту програми як є.`},{title:`Повільніший приріст з часом`,text:`Початківці часто покращуються швидко, почасти тому що вчать рухи. Досвідчені атлети прогресують повільніше та меншими кроками. Ріст м’язів потребує часу для вимірювання, тож незмінні ваги чи одиничний тест результативності не доводять, що ваше тренування провалилося. Якщо у вас незрозуміла втома чи інші симптоми здоров’я, що тривають, проконсультуйтеся з лікарем.`},{title:`Як це працює в TrainUp`,text:`Історія показує ваші тренування, середнє зусилля та графік за 4 тижні, що може допомогти помітити можливе плато. TrainUp ніколи не змінює ваш план на основі менш ніж 3 тренувань, тож один важкий день не запускає нову програму. Робіть невеликі коригування й перевіряйте знову після кількох занять.`}];var l=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: безпека та основи силових тренувань`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Рекомендації ACSM щодо моделі прогресії`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};